auto parse_and_create_config = [&](absl::string_view name, Json json) -> Json {
  auto result = AuditLoggerRegistry::ParseConfig(name, json);
  if (!result.ok()) {
    errors->AddError(result.status().message());
    return Json();
  }
  return Json::FromObject({{std::string(name), std::move(json)}});
};
absl::optional<Json> result = Match(
    extension->value,
    [&](absl::string_view serialized_value) -> absl::optional<Json> {
      auto config_factory_it =
          audit_logger_config_factories_.find(extension->type);
      if (config_factory_it != audit_logger_config_factories_.end()) {
        return parse_and_create_config(
            config_factory_it->second->name(),
            Json::FromObject(
                config_factory_it->second->ConvertXdsAuditLoggerConfig(
                    context, serialized_value, errors)));
      }
      return absl::nullopt;
    },
    [&](const Json& json) -> absl::optional<Json> {
      if (AuditLoggerRegistry::FactoryExists(extension->type)) {
        return parse_and_create_config(extension->type, json);
      }
      return absl::nullopt;
    });
if (result.has_value()) return std::move(*result);

